			boolean tf = true;
			for(int i = 0; i < T.length(); i++){
				if(s.charAt(i) != '?' && s.charAt(i) != T.charAt(i)){
					tf = false;
					break;
				}
			}

			if(tf){
				SS = new StringBuilder(SS).replace(index, index + s.length(), T).toString();
				SS = SS.replace('?', 'a');
				System.out.println(SS);
				return;
			}else{
				index--;
			}
		}

		System.out.println("UNRESTORABLE");
	}
