					}
				}
				else{
					if(field[0][i]==-1){

					}
					else{
						if(!dp[0][i-1].equals("0")&&!dp[0][i-1].equals("")){
							dp[0][i]=dp[0][i-1]+field[0][i];
						}
						else{
							dp[0][i]=""+field[0][i];
						}
