					}

				}
				else{
					if(field[i][0]==-1){

					}
					else{
						if(!dp[i-1][0].equals("0")&&!dp[i-1][0].equals("")){
							dp[i][0]=dp[i-1][0]+field[i][0];
						}
						else{
							dp[i][0]=""+field[i][0];
						}
					}
				}
			}
			String ans="0";
			for(int i = 1;i<h;i++){
				for(int j = 1;j<w;j++){
					if(field[i][j]==-1)continue;
					String s1=dp[i-1][j]+field[i][j];
					String s2=dp[i][j-1]+field[i][j];
					String s3=field[i][j]+"";
					if(big(s1,s2)>=0){
						if(big(s1,s3)>=0){
							dp[i][j]=s1;
						}
						else{
							dp[i][j]=s3;
						}
					}
					else{
						if(big(s2,s3)>=0){
							dp[i][j]=s2;
						}
						else{
							dp[i][j]=s3;
						}
					}
					while(dp[i][j].charAt(0)=='0'&&dp[i][j].length()>1){
						dp[i][j]=dp[i][j].substring(1,dp[i][j].length());
					}
					if(big(dp[i][j],ans)>0){
						ans=dp[i][j];
					}
				}
			}
			for(int i = 0;i<h;i++){
				for(int j = 0;j<w;j++){
					if(big(dp[i][j],ans)>0){
						ans=dp[i][j];
					}
				}
			}
			//output();
			System.out.println(ans);
		}

	}
	static int big(String s1,String s2){
		if(s1.length()==s2.length()){
			return s1.compareTo(s2);
		}
		return s1.length()-s2.length();
	}
	static void output(){
		for(int i = 0;i<h;i++){
			for(int j = 0;j<w;j++){
				System.out.print(dp[i][j]+" ");
			}
			System.out.println();
		}
		System.out.println();
	}
