		for(int i = 0;i < N;i++){
			a[i] = nextInt() - 1;
		}
		boolean[] used = new boolean[N];
		int ans = 0;
		for(int i = 0;i < N;i++){
			int x = a[i];
			int y = a[x];
			if(used[x])continue;
			if(used[y])continue;
			if(x == a[y] && y == a[x]){
				ans++;
				used[x] = true;
				used[y] = true;
			}
		}
		out.println(ans);
	}

