	private void solve() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int[] a = new int[N];
		for (int j = 0; j < N; j++) {
			a[j] = sc.nextInt();
		}
		boolean[] dp = new boolean[K + 1];
		for (int i = 0; i <= K; i++) {
			boolean isWin = false;
			for (int j = 0; j < N; j++) {
				if (a[j] <= i && !dp[i - a[j]]) {
					isWin = true;
					break;
				}
			}
			dp[i] = isWin;
		}
		System.out.println(dp[K] ? "First" : "Second");
	}

	class Scanner {
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int index;
		private int length;

		public Scanner(InputStream in) {
			this.in = in;
		}

		private boolean isPrintableChar(int c) {
			return '!' <= c && c <= '~';
		}

		private boolean isDigit(int c) {
			return '0' <= c && c <= '9';
		}

		private boolean hasNextByte() {
			if (index < length) {
				return true;
			} else {
				try {
					length = in.read(buffer);
					index = 0;
				} catch (IOException e) {
					e.printStackTrace();
				}
				return length > 0;
			}
		}

		private boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[index])) {
				index++;
			}
			return hasNextByte();
		}

		private int readByte() {
			return hasNextByte() ? buffer[index++] : -1;
		}

		public String next() {
			if (!hasNext()) {
				throw new RuntimeException("no input");
			}
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext()) {
				throw new RuntimeException("no input");
			}
			long value = 0L;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			while (isPrintableChar(b)) {
				if (isDigit(b)) {
					value = value * 10 + (b - '0');
				}
				b = readByte();
			}
			return minus ? -value : value;
		}

		public int nextInt() {
			return (int)nextLong();
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}

	interface CombCalculator {
		long comb(int n, int m);
	}

	interface MobiusFunction {
		int get(int n);
	}

	/**
	 * „É°„Éì„Ç¶„ÇπÈñ¢Êï∞„Çí„Ç®„É©„Éà„Çπ„ÉÜ„Éç„Çπ„ÅÆÁØ©„Å£„ÅΩ„ÅèÂâçË®àÁÆó„Åô„Çã„ÇØ„É©„Çπ„Åß„Åô„ÄÇ
	 * Ë®àÁÆóÈáè„ÅØO(1)„Åß„ÄÅÂâçË®àÁÆó„ÅßO(N logN)„Åß„Åô„ÄÇ
	 */
	class SieveMobiusFunction implements MobiusFunction {
		int size;
		int[] mobiusFunctionValues;

		public SieveMobiusFunction(int size) {
			this.size = size;
			mobiusFunctionValues = new int[size];

			mobiusFunctionValues[0] = 0;
			mobiusFunctionValues[1] = 1;
			for (int i = 2; i < size; i++) {
				mobiusFunctionValues[i] = 1;
			}
			for (int i = 2; i * i < size; i++) {
				for (int k = 1; i * i * k < size; k++) {
					mobiusFunctionValues[i * i * k] *= 0;
				}
			}

			for (int i = 2; i < size; i++) {
				if (mobiusFunctionValues[i] == 1) {
					for (int k = 1; i * k < size; k++) {
						mobiusFunctionValues[i * k] *= -2;
					}
				}
				if (mobiusFunctionValues[i] > 1) {
					mobiusFunctionValues[i] = 1;
				}
				if (mobiusFunctionValues[i] < -1) {
					mobiusFunctionValues[i] = -1;
				}
			}
		}

		@Override
		public int get(int n) {
			if (n > size) {
				throw new RuntimeException("n is greater than size.");
			}
			if (n < 0) {
				return 0;
			}
			return mobiusFunctionValues[n];
		}
	}

	/**
	 * „É°„Éì„Ç¶„ÇπÈñ¢Êï∞„ÇíÂÆöÁæ©ÈÄö„ÇäË®àÁÆó„Åô„Çã„ÇØ„É©„Çπ„Åß„Åô„ÄÇ
	 * Ë®àÁÆóÈáè„ÅØO(logN)„Åß„Åô„ÄÇ
	 */
	class PrimeFactorizationMobiusFunction implements MobiusFunction {
		@Override
		public int get(int n) {
			if (n <= 0) {
				return 0;
			}
			if (n == 1) {
				return 1;
			}
			int num = 0;
			for (int i = 2; i < n; i++) {
				if (n % i == 0) {
					n /= i;
					num++;
					if (n % i == 0) {
						return 0;
					}
				}
			}
			return num % 2 == 0 ? -1 : 1;
		}
	}

	/**
	 * ÁµÑ„ÅøÂêà„Çè„ÅõË®àÁÆó„ÇíÈöé‰πó„ÅÆÂÄ§„ÅßË°å„ÅÜ„ÇØ„É©„Çπ„Åß„Åô(MODÂØæÂøú)
	 * Èöé‰πó„Å®„Åù„ÅÆÈÄÜÂÖÉ„ÅØÂâçË®àÁÆó„Åó„Å¶„ÉÜ„Éº„Éñ„É´„Å´Ê†ºÁ¥ç„Åó„Åæ„Åô„ÄÇ
	 * C(N, N) % M „ÅÆË®àÁÆóÈáè„ÅØ O(1)„ÄÅ ÂâçË®àÁÆó„ÅßO(max(N, logM))„Åß„Åô„ÄÇ
	 * size„Çí1e8„Çà„ÇäÂ§ß„Åç„ÅÑÂÄ§„ÅßÂÆüË°å„Åô„Çã„Å®MLE„ÅÆÂç±Èô∫ÊÄß„Åå„ÅÇ„Çä„Åæ„Åô„ÄÇ
	 * „Åæ„ÅüÁ¥†Êï∞‰ª•Â§ñ„ÅÆMOD„Å´„ÅØÂØæÂøú„Åó„Å¶„ÅÑ„Åæ„Åõ„Çì(ÈÄÜÂÖÉ„ÅÆË®àÁÆó„Å´Á¥†Êï∞„ÅÆÂâ∞‰ΩôÁí∞„ÅÆÊÄßË≥™„ÇíÂà©Áî®„Åó„Å¶„ÅÑ„Çã„Åü„ÇÅ)„ÄÇ
	 */
	class FactorialTableCombCalculator implements CombCalculator {
		int size;
		long[] factorialTable;
		long[] inverseFactorialTable;
		long mod;

		public FactorialTableCombCalculator(int size, long mod) {
			this.size = size;
			factorialTable = new long[size + 1];
			inverseFactorialTable = new long[size + 1];
			this.mod = mod;

			factorialTable[0] = 1L;
			for (int i = 1; i <= size; i++) {
				factorialTable[i] = (factorialTable[i - 1] * i) % mod;
			}
			inverseFactorialTable[size] = inverse(factorialTable[size], mod);
			for (int i = size - 1; i >= 0; i--) {
				inverseFactorialTable[i] = (inverseFactorialTable[i + 1] * (i + 1)) % mod;
			}
		}

		private long inverse(long n, long mod) {
			return pow(n, mod - 2, mod);
		}

		private long pow(long n, long p, long mod) {
			if (p == 0) {
				return 1L;
			}
			long half = pow(n, p / 2, mod);
			long ret = (half * half) % mod;
			if (p % 2 == 1) {
				ret = (ret * n) % mod;
			}
			return ret;
		}

		@Override
		public long comb(int n, int m) {
			if (n > size) {
				throw new RuntimeException("n is greater than size.");
			}
			if (n < 0 || m < 0 || n < m) {
				return 0L;
			}
			return (((factorialTable[n] * inverseFactorialTable[m]) % mod) * inverseFactorialTable[n - m]) % mod;
		}
	}

	/**
	 * ÁµÑ„ÅøÂêà„Çè„ÅõË®àÁÆó„Çí„ÉÜ„Éº„Éñ„É´„ÅßÂÆüË£Ö„Åó„Åü„ÇØ„É©„Çπ„Åß„Åô(MODÂØæÂøú)
	 * ÂâçË®àÁÆó„ÅßO(N^2), comb„ÅØO(1)„ÅßÂÆüË°å„Åß„Åç„Åæ„Åô
	 * size„Çí2 * 1e4„Çà„ÇäÂ§ß„Åç„ÅÑÂÄ§„ÅßÂÆüË°å„Åô„Çã„Å®MLE„ÅÆÂç±Èô∫ÊÄß„Åå„ÅÇ„Çä„Åæ„Åô
	 */
	class TableCombCalculator implements CombCalculator {
		long[][] table;
		int size;

		public TableCombCalculator(int size, long mod) {
			this.size = size;
			table = new long[size + 1][];

			table[0] = new long[1];
			table[0][0] = 1L;
			for (int n = 1; n <= size; n++) {
				table[n] = new long[n + 1];
				table[n][0] = 1L;
				for (int m = 1; m < n; m++) {
					table[n][m] = (table[n - 1][m - 1] + table[n - 1][m]) % mod;
				}
				table[n][n] = 1L;
			}
		}

		@Override
		public long comb(int n, int m) {
			if (n > size) {
				throw new RuntimeException("n is greater than size.");
			}
			if (n < 0 || m < 0 || n < m) {
				return 0L;
			}
			return table[n][m];
		}
	}

	interface Graph {
		void link(int from, int to, long cost);
		Optional<Long> getCost(int from, int to);
		int getVertexNum();
	}

	interface FlowResolver {
		long maxFlow(int from, int to);
	}

	/**
	 * „Ç∞„É©„Éï„ÅÆË°åÂàó„Å´„Çà„ÇãÂÆüË£Ö
	 * Êé•ÁÇπÊï∞„ÅÆÂ§ß„Åç„ÅÑ„Ç∞„É©„Éï„Åß‰Ωø„ÅÜ„Å®MLE„ÅßÊ≠ª„Å´„Åù„ÅÜ
	 */
	class ArrayGraph implements Graph {
		private Long[][] costArray;
		private int vertexNum;

		public ArrayGraph(int n) {
			costArray = new Long[n][];
			for (int i = 0; i < n; i++) {
				costArray[i] = new Long[n];
			}
			vertexNum = n;
		}

		@Override
		public void link(int from, int to, long cost) {
			costArray[from][to] = new Long(cost);
		}

		@Override
		public Optional<Long> getCost(int from, int to) {
			return Optional.ofNullable(costArray[from][to]);
		}

		@Override
		public int getVertexNum() {
			return vertexNum;
		}
	}

	/**
	 * DFS(Ê∑±„ÅïÂÑ™ÂÖàÊé¢Á¥¢)„Å´„Çà„ÇãÂÆüË£Ö
	 * Ë®àÁÆóÈáè„ÅØO(E*MaxFlow)„ÅÆ„ÅØ„Åö (E:Ëæ∫„ÅÆÊï∞, MaxFlow:ÊúÄÂ§ß„Éï„É≠„Éº)
	 */
	class DfsFlowResolver implements FlowResolver {
		private Graph graph;
		public DfsFlowResolver(Graph graph) {
			this.graph = graph;
		}

		/**
		 * ÊúÄÂ§ß„Éï„É≠„Éº(ÊúÄÂ∞è„Ç´„ÉÉ„Éà)„ÇíÊ±Ç„ÇÅ„Çã
		 * @param from ÂßãÁÇπ(source)„ÅÆID
		 * @param to ÁµÇÁÇπ(target)„ÅÆID
		 * @return ÊúÄÂ§ß„Éï„É≠„Éº(ÊúÄÂ∞è„Ç´„ÉÉ„Éà)
		 */
		public long maxFlow(int from, int to) {
			long sum = 0L;
			long currentFlow;
			do {
				currentFlow = flow(from, to, Long.MAX_VALUE / 3, new boolean[graph.getVertexNum()]);
				sum += currentFlow;
			} while (currentFlow > 0);
			return sum;
		}

		/**
		 * „Éï„É≠„Éº„ÅÆÂÆüË°å „Ç∞„É©„Éï„ÅÆÊõ¥Êñ∞„ÇÇË°å„ÅÜ
		 * @param from ÁèæÂú®„ÅÑ„ÇãÁØÄÁÇπ„ÅÆID
		 * @param to ÁµÇÁÇπ(target)„ÅÆID
		 * @param current_flow „Åì„Åì„Åæ„Åß„ÅÆÊµÅÈáè
		 * @param passed Êó¢„Å´ÈÄö„Å£„ÅüÁØÄÁÇπ„ÅãÂê¶„Åã„ÇíÊ†ºÁ¥ç„Åó„ÅüÈÖçÂàó
		 * @return ÁµÇÁÇπ(target)„Å´ÊµÅ„Åó„ÅüÊµÅÈáè/Êàª„Çä„ÅÆ„Ç∞„É©„Éï„ÅÆÊµÅÈáè
		 */
		private long flow(int from, int to, long current_flow, boolean[] passed) {
			passed[from] = true;
			if (from == to) {
				return current_flow;
			}
			for (int id = 0; id < graph.getVertexNum(); id++) {
				if (passed[id]) {
					continue;
				}
				Optional<Long> cost = graph.getCost(from, id);
				if (cost.orElse(0L) > 0) {
					long nextFlow = current_flow < cost.get() ? current_flow : cost.get();
					long returnFlow = flow(id, to, nextFlow, passed);
					if (returnFlow > 0) {
						graph.link(from, id, cost.get() - returnFlow);
						graph.link(id, from, graph.getCost(id, from).orElse(0L) + returnFlow);
						return returnFlow;
					}
				}
			}
			return 0L;
		}
	}

	/**
	 * 1-indexed„ÅÆBITÈÖçÂàó
	 */
	class BinaryIndexedTree {
		private long[] array;

		public BinaryIndexedTree(int size) {
			this.array = new long[size + 1];
		}

		/**
		 * ÊåáÂÆö„Åó„ÅüË¶ÅÁ¥†„Å´ÂÄ§„ÇíÂä†ÁÆó„Åô„Çã
		 * Ë®àÁÆóÈáè„ÅØO(logN)
		 * @param index Âä†ÁÆó„Åô„ÇãË¶ÅÁ¥†„ÅÆÊ∑ªÂ≠ó
		 * @param value Âä†ÁÆó„Åô„ÇãÈáè
		 */
		public void add(int index, long value) {
			for (int i = index; i < array.length; i += (i & -i)) {
				array[i] += value;
			}
		}

		/**
		 * 1„ÄúÊåáÂÆö„Åó„ÅüË¶ÅÁ¥†„Åæ„Åß„ÅÆÂíå„ÇíÂèñÂæó„Åô„Çã
		 * Ë®àÁÆóÈáè„ÅØO(logN)
		 * @param index Âíå„ÅÆÁµÇÁ´Ø„Å®„Å™„ÇãË¶ÅÁ¥†„ÅÆÊ∑ªÂ≠ó
		 * @return 1„Äúindex„Åæ„Åß„ÅÆÂíå
		 */
		public long getSum(int index) {
			long sum = 0L;
			for (int i = index; i > 0; i -= (i & -i)) {
				sum += array[i];
			}
			return sum;
		}
	}

	/**
	 * 1-indexed„ÅÆ2Ê¨°ÂÖÉBITÈÖçÂàó
	 */
	class BinaryIndexedTree2D {
		private long[][] array;

		public BinaryIndexedTree2D(int size1, int size2) {
			this.array = new long[size1 + 1][];
			for (int i = 1; i <= size1; i++) {
				this.array[i] = new long[size2 + 1];
			}
		}

		/**
		 * ÊåáÂÆö„Åó„ÅüË¶ÅÁ¥†„Å´ÂÄ§„ÇíÂä†ÁÆó„Åô„Çã
		 * Ë®àÁÆóÈáè„ÅØO(logN * logN)
		 * @param index1 Âä†ÁÆó„Åô„ÇãË¶ÅÁ¥†„ÅÆ1Ê¨°ÂÖÉÁõÆ„ÅÆÊ∑ªÂ≠ó
		 * @param index2 Âä†ÁÆó„Åô„ÇãË¶ÅÁ¥†„ÅÆ2Ê¨°ÂÖÉÁõÆ„ÅÆÊ∑ªÂ≠ó
		 * @param value Âä†ÁÆó„Åô„ÇãÈáè
		 */
		public void add(int index1, int index2, long value) {
			for (int i1 = index1; i1 < array.length; i1 += (i1 & -i1)) {
				for (int i2 = index2; i2 < array.length; i2 += (i2 & -i2)) {
					array[i1][i2] += value;
				}
			}
		}

		/**
		 * (1,1)„ÄúÊåáÂÆö„Åó„ÅüË¶ÅÁ¥†„Åæ„Åß„ÅÆÁü©ÂΩ¢Âíå„ÇíÂèñÂæó„Åô„Çã
		 * Ë®àÁÆóÈáè„ÅØO(logN * logN)
		 * @param index1 Âíå„ÅÆÁµÇÁ´Ø„Å®„Å™„ÇãË¶ÅÁ¥†„ÅÆ1Ê¨°ÂÖÉÁõÆ„ÅÆÊ∑ªÂ≠ó
		 * @param index2 Âíå„ÅÆÁµÇÁ´Ø„Å®„Å™„ÇãË¶ÅÁ¥†„ÅÆ2Ê¨°ÂÖÉÁõÆ„ÅÆÊ∑ªÂ≠ó
		 * @return (1,1)„Äú(index1,index2)„Åæ„Åß„ÅÆÁü©ÂΩ¢Âíå
		 */
		public long getSum(int index1, int index2) {
			long sum = 0L;
			for (int i1 = index1; i1 > 0; i1 -= (i1 & -i1)) {
				for (int i2 = index2; i2 > 0; i2 -= (i2 & -i2)) {
					sum += array[i1][i2];
				}
			}
			return sum;
		}
	}

	interface UnionFind {
		void union(int A, int B);
		boolean judge(int A, int B);
		Set<Integer> getSet(int id);
	}

	/**
	 * ArrayUnionFind„ÅÆÊã°Âºµ
	 * MapSet„ÅßÊ†π„ÅÆÊ∑ªÂ≠ó„Åã„ÇâÊ†π„Å´„Å∂„Çâ‰∏ã„Åå„ÇãÈ†ÇÁÇπ„ÅÆÈõÜÂêà„ÅåÂèñÂæó„Åß„Åç„Çã„Çà„ÅÜ„Å´„Åó„Åü
	 * getSet„É°„ÇΩ„ÉÉ„Éâ„ÇíO(logN * logN)„Å´ËêΩ„Å®„Åõ„Å¶„ÅÑ„Çã„ÅØ„Åö
	 * „Åü„Å†„Åóunion„É°„ÇΩ„ÉÉ„Éâ„ÅØ2ÂÄç„ÅÆË®àÁÆóÈáè„Å´„Å™„Å£„Å¶„ÅÑ„Çã„ÅÆ„ÅßÊ≥®ÊÑè(„Ç™„Éº„ÉÄ„Éº„ÅØÂ§â„Çè„Çâ„Å™„ÅÑ„ÅØ„Åö)
	 */
	class SetUnionFind extends ArrayUnionFind {
		Map<Integer, Set<Integer>> map;
		public SetUnionFind(int size) {
			super(size);
			map = new HashMap<>();
			for (int i = 0; i < size; i++) {
				map.put(i, new HashSet<>());
				map.get(i).add(i);
			}
		}

		@Override
		protected void unionTo(int source, int dest) {
			super.unionTo(source, dest);
			map.get(dest).addAll(map.get(source));
		}

		@Override
		public Set<Integer> getSet(int id) {
			return map.get(root(id));
		}
	}

	/**
	 * ÈÖçÂàó„Å´„Çà„ÇãUnionFind„ÅÆÂÆüË£Ö
	 * getSet„É°„ÇΩ„ÉÉ„Éâ„ÅØO(NlogN)„Å™„ÅÆ„ÅßTLE„Å´Ê≥®ÊÑè
	 */
	class ArrayUnionFind implements UnionFind {
		int[] parent;
		int[] rank;
		int size;
		public ArrayUnionFind(int size) {
			parent = new int[size];
			for (int i = 0; i < size; i++) {
				parent[i] = i;
			}
			rank = new int[size];
			this.size = size;
		}

		@Override
		public void union(int A, int B) {
			int rootA = root(A);
			int rootB = root(B);
			if (rootA != rootB) {
				if (rank[rootA] < rank[rootB]) {
					unionTo(rootA, rootB);
				} else {
					unionTo(rootB, rootA);
					if (rank[rootA] == rank[rootB]) {
						rank[rootA]++;
					}
				}
			}
		}

		protected void unionTo(int source, int dest) {
			parent[source] = dest;
		}

		@Override
		public boolean judge(int A, int B) {
			return root(A) == root(B);
		}

		@Override
		public Set<Integer> getSet(int id) {
			Set<Integer> set = new HashSet<>();
			IntStream.range(0, size).filter(i -> judge(i, id)).forEach(set::add);
			return set;
		}

		protected int root(int id) {
			if (parent[id] == id) {
				return id;
			}
			parent[id] = root(parent[id]);
			return parent[id];
		}
	}

	/**
	 * Á¥†Êï∞„ÅÆ„É¶„Éº„ÉÜ„Ç£„É™„ÉÜ„Ç£
	 */
	class PrimeNumberUtils {
		boolean[] isPrimeArray;
		List<Integer> primes;

		/**
		 * Á¥†Êï∞Âà§ÂÆö„ÅÆ‰∏äÈôê„Å®„Å™„ÇãÂÄ§„ÇíÊåáÂÆö„Åó„Å¶„É¶„Éº„ÉÜ„Ç£„É™„ÉÜ„Ç£„ÇíÂàùÊúüÂåñ
		 * @param limit Á¥†Êï∞Âà§ÂÆö„ÅÆ‰∏äÈôê(„Åì„ÅÆÂÄ§‰ª•‰∏ä„ÅåÁ¥†Êï∞„Åß„ÅÇ„Çã„ÅãÂà§ÂÆö„Åó„Å™„ÅÑ)
		 */
		public PrimeNumberUtils(int limit) {
			if (limit > 10000000) {
				System.err.println("‰∏äÈôê„ÅÆÂÄ§„ÅåÈ´ò„Åô„Åé„Çã„Åü„ÇÅÁ¥†Êï∞„É¶„Éº„ÉÜ„Ç£„É™„ÉÜ„Ç£„ÅÆÂàùÊúüÂåñ„ÅßTLE„Åô„ÇãÂèØËÉΩÊÄß„ÅåÂ§ßÂ§âÈ´ò„ÅÑ„Åß„Åô");
			}
			primes = new ArrayList<>();
			isPrimeArray = new boolean[limit];
			if (limit > 2) {
				primes.add(2);
				isPrimeArray[2] = true;
			}

			for (int i = 3; i < limit; i += 2) {
				if (isPrime(i, primes)) {
					primes.add(i);
					isPrimeArray[i] = true;
				}
			}
		}

		public List<Integer> getPrimeNumberList() {
			return primes;
		}

		public boolean isPrime(int n) {
			return isPrimeArray[n];
		}

		private boolean isPrime(int n, List<Integer> primes) {
			for (int prime : primes) {
				if (n % prime == 0) {
					return false;
				}
				if (prime > Math.sqrt(n)) {
					break;
				}
			}
			return true;
		}
	}

	interface BitSet {
		void set(int index, boolean bit);
		boolean get(int index);
		void shiftRight(int num);
		void shiftLeft(int num);
		void or(BitSet bitset);
		void and(BitSet bitset);
	}

	/**
	 * Long„ÅÆÈÖçÂàó„Å´„Çà„ÇãBitSet„ÅÆÂÆüË£Ö
	 * get/set„ÅØO(1)
	 * shift/or/and„ÅØO(size / 64)
	 */
	class LongBit implements BitSet {
		long[] bitArray;

		public LongBit(int size) {
			bitArray = new long[((size + 63) / 64)];
		}

		@Override
		public void set(int index, boolean bit) {
			int segment = index / 64;
			int inIndex = index % 64;
			if (bit) {
				bitArray[segment] |= 1L << inIndex;
			} else {
				bitArray[segment] &= ~(1L << inIndex);
			}
		}

		@Override
		public boolean get(int index) {
			int segment = index / 64;
			int inIndex = index % 64;
			return (bitArray[segment] & (1L << inIndex)) != 0L;
		}

		@Override
		public void shiftRight(int num) {
			int shiftSeg = num / 64;
			int shiftInI = num % 64;
			for (int segment = 0; segment < bitArray.length; segment++) {
				int sourceSeg = segment + shiftSeg;
				if (sourceSeg < bitArray.length) {
					bitArray[segment] = bitArray[sourceSeg] >>> shiftInI;
					if (shiftInI > 0 && sourceSeg + 1 < bitArray.length) {
						bitArray[segment] |= bitArray[sourceSeg + 1] << (64 - shiftInI);
					}
				} else {
					bitArray[segment] = 0L;
				}
			}
		}

		@Override
		public void shiftLeft(int num) {
			int shiftSeg = num / 64;
			int shiftInI = num % 64;
			for (int segment = bitArray.length - 1; segment >= 0; segment--) {
				int sourceSeg = segment - shiftSeg;
				if (sourceSeg >= 0) {
					bitArray[segment] = bitArray[sourceSeg] << shiftInI;
					if (shiftInI > 0 && sourceSeg > 0) {
						bitArray[segment] |= bitArray[sourceSeg - 1] >>> (64 - shiftInI);
					}
				} else {
					bitArray[segment] = 0L;
				}
			}
		}

		public long getLong(int segment) {
			return bitArray[segment];
		}

		@Override
		public void or(BitSet bitset) {
			if (!(bitset instanceof LongBit)) {
				return;
			}
			for (int segment = 0; segment < bitArray.length; segment++) {
				bitArray[segment] |= ((LongBit)bitset).getLong(segment);
			}
		}

		@Override
		public void and(BitSet bitset) {
			if (!(bitset instanceof LongBit)) {
				return;
			}
			for (int segment = 0; segment < bitArray.length; segment++) {
				bitArray[segment] &= ((LongBit)bitset).getLong(segment);
			}
		}
	}

