    }
    if(checkEven(ni)){
      even++;
    }else{
      odd++;
    }
    if(checkEven(san)){
      even++;
    }else{
      odd++;
    }

    if(checkEven(si)){
      even++;
    }else{
      odd++;
    }

      if(odd == 2 && even == 2)
      {
        System.out.println("YES");
